import logging
from collections import OrderedDict
from random import randint
from taf.gnb.oam.ne3s.ws.components.base import FunctionalComponent
from taf.gnb.oam.ne3s.ws.filter import MessageStream, MessageRule
from taf.gnb.oam.ne3s.ws.components.FM.v1.resources.notifications.messages import (
    ActiveFaults, FMNotificationGroup)
from taf.gnb.oam.ne3s.ws.exceptions import StreamTimeoutError
from taf.gnb.oam.ne3s.ws.components.FM.v1.resources.templates import templates
from taf.gnb.oam.ne3s.ws.components.connection.exceptions import NE3SRequestFailed
from taf.gnb.oam.ne3s.ws.components.connection.ne3s_service import NE3SService
from taf.gnb.oam.ne3s.ws.components.exceptions import OperationFailed, OperationTimeout

log = logging.getLogger("taf.gnb.oam.ne3s.ws.logger")


class FMv1(FunctionalComponent):
    DEFAULT_ADAPTATION_VERSION = 'MRBTS-1900'
    STREAMS = None
    _connection = None
    SUPPORTED_NOTIFICATIONS = FMNotificationGroup

    def __init__(self, connection):
        self._connection = connection
        self.fm_all_notifications = MessageStream(name="FM.all", rule=MessageRule(condition=(ActiveFaults,)))
        self.STREAMS = [self.fm_all_notifications]

    def get_active_faults(self, timeout=10):
        stream_name = "FM.get_active_faults"

        active_faults_stream = self.add_new_msg_stream(stream_name=stream_name, msg_list=[ActiveFaults])
        try:
            upload_type = 'active_faults'
            self.request_active_faults_upload(upload_type)
            active_faults_msg = active_faults_stream.get(timeout=timeout)
            return active_faults_msg.alarms

        except NE3SRequestFailed as e:
            err_msg = "Could not get active faults due to NE3S Request Failure with Error: {}".format(e)
            raise OperationFailed(err_msg)

        except StreamTimeoutError as e:
            err_msg = "Requested active faults were not provided in requested time, Error: {}".format(e)
            raise OperationTimeout(err_msg)

        finally:
            self.remove_msg_stream(stream_name=stream_name)

    def request_active_faults_upload(self, upload_type):
        url = self._connection.create_soap_service_url(NE3SService.BULK)
        upload_action = 'upload'

        upload_content = templates.get_file_content('upload.xml', 'r')

        upload_content = upload_content.format(
            manager_registration_key=self._connection.REGISTRATION_KEY,
            session_id=self._connection.session_id,
            manager_id=self._connection.connection_details.manager_id,
            operation_id=randint(1, 100000),
            upload_type=upload_type
        )

        cid_soap = '1234a@apache.org'

        log.debug("Configuration request upload content {}".format(upload_content))

        header_soap = {'Content-ID': '<{}>'.format(cid_soap)}

        fields = OrderedDict()
        fields[cid_soap] = (cid_soap, upload_content, 'text/xml; charset=UTF-8', header_soap)

        upload_response = self._connection.send_multipart_soap_message(url, fields, upload_action)

        log.debug("Configuration upload response: {}".format(upload_response))
        return upload_response
